const COURSES=window.DASLONGO_COURSES;
const LESSONS=window.DASLONGO_LESSONS;
const CATALOG=window.DASLONGO_CATALOG;
    const CHARACTERS=window.DASLONGO_CHARACTERS;

    const KEY="daslongo-v1";
    function localDateKey(date=new Date()){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`}
    const defaults={course:"python",enrolledCourses:["python"],customCourses:[],coursePreferences:{},xp:0,xpEarned:0,hearts:3,lastHeartAt:Date.now(),streak:0,bestStreak:0,shields:0,lastVisit:"",dailyDate:localDateKey(),dailyModules:0,challengeDate:"",challengeCount:0,goal:10,goalXp:0,referral:"",level:"Boshlovchi",name:"O‘rganuvchi",companion:"momi",unlockedCharacters:["momi"],completed:{},onboarded:false};
    let state=loadState(),view="learn",lesson=null,onboardStep=0,onboardData={referral:"",goal:10,level:"Boshlovchi",name:""},authUser=null,authReady=false,onboardingUserId="",learnerCounts={},learnerCountsStatus="loading",lastEnrollmentSyncUserId="";
    function loadState(){try{const saved=JSON.parse(localStorage.getItem(KEY)||"{}"),loaded={...defaults,...saved};if(!Number.isFinite(saved.xpEarned))loaded.xpEarned=loaded.xp;if(!Number.isFinite(saved.bestStreak))loaded.bestStreak=loaded.streak;if(!Array.isArray(loaded.unlockedCharacters))loaded.unlockedCharacters=["momi"];if(!Array.isArray(loaded.customCourses))loaded.customCourses=[];if(!Array.isArray(loaded.enrolledCourses))loaded.enrolledCourses=[loaded.course||"python"];if(!loaded.coursePreferences||typeof loaded.coursePreferences!=="object")loaded.coursePreferences={};if(!CHARACTERS.some(c=>c.id===loaded.companion))loaded.companion="momi";loaded.hearts=Math.max(0,Math.min(3,Number(loaded.hearts)||0));if(!loaded.enrolledCourses.includes(loaded.course))loaded.enrolledCourses.push(loaded.course);if(loaded.dailyDate!==defaults.dailyDate){loaded.dailyDate=defaults.dailyDate;loaded.dailyModules=0;loaded.goalXp=0;localStorage.setItem(KEY,JSON.stringify(loaded))}return loaded}catch(error){console.warn("Saqlangan holatni o‘qib bo‘lmadi:",error);return {...defaults}}}
    function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch(error){console.error("Holatni saqlab bo‘lmadi:",error);showToast("Ma’lumotni saqlash imkoni bo‘lmadi.")}}
    function courseList(){return [...COURSES,...CATALOG,...state.customCourses]}
    function course(){return courseList().find(c=>c.id===state.course)||COURSES[2]}
    function courseLesson(selectedCourse,index){return selectedCourse.curriculum?.[index]||LESSONS[selectedCourse.id]?.[index]}
    function companion(){return CHARACTERS.find(c=>c.id===state.companion)||CHARACTERS[0]}
    function completedCount(){return (state.completed[state.course]||[]).length}
    function refreshDailyState(){const today=localDateKey();if(state.dailyDate!==today){state.dailyDate=today;state.dailyModules=0;state.goalXp=0;save()}}
    function maxHearts(){return authUser?.app_metadata?.daslongo_plus===true?5:3}
    function heartRefresh(){const limit=maxHearts();if(state.hearts<limit){const passed=Date.now()-state.lastHeartAt;const recovered=Math.floor(passed/86400000);if(recovered){state.hearts=Math.min(limit,state.hearts+recovered);state.lastHeartAt=state.hearts===limit?Date.now():state.lastHeartAt+recovered*86400000;save()}}}
    function render(){const landing=document.getElementById("landing-page"),app=document.getElementById("app"),mobileNav=document.querySelector(".mobile-nav");if(!authReady||!authUser){landing.classList.remove("hidden");app.classList.add("hidden");mobileNav.classList.add("hidden");return}landing.classList.add("hidden");app.classList.remove("hidden");mobileNav.classList.remove("hidden");refreshDailyState();heartRefresh();document.getElementById("course-icon").textContent=course().icon;document.getElementById("current-course-name").textContent=course().name;document.getElementById("heart-count").textContent=state.hearts;document.getElementById("heart-limit").textContent=`/${maxHearts()}`;document.getElementById("xp-count").textContent=state.xp;document.getElementById("streak-count").textContent=state.streak;document.getElementById("goal-label").textContent=`${state.goal} daqiqa`;document.getElementById("goal-value").textContent=`${Math.min(state.goalXp,state.goal*2)} / ${state.goal*2} XP`;document.getElementById("goal-bar").style.width=`${Math.min(100,state.goalXp/(state.goal*2)*100)}%`;updateAccountUI();renderQuests();renderView()}
    function renderQuests(){const rows=[["⚡","Modul yakunlang",Math.min(1,state.dailyModules),1],["✦","Kunlik chaqiriq",state.challengeDate===state.dailyDate?1:0,1],["📚","10 XP to‘plang",Math.min(10,state.goalXp),10]];document.getElementById("quests-list").innerHTML=rows.map(([icon,label,n,max])=>`<div class="quest"><div class="quest-icon">${icon}</div><div class="flex-1"><div class="quest-label">${label}</div><div class="quest-progress"><span style="width:${n/max*100}%"></span></div></div><span class="quest-count">${n}/${max}</span></div>`).join("");document.getElementById("quest-total").textContent=`${rows.filter(x=>x[2]>=x[3]).length}/3`}
    function navigateTo(nextView){if(!authUser){openAccount("login");return}view=nextView;renderView();window.scrollTo({top:0,behavior:"smooth"})}
    function renderView(){document.querySelectorAll("[data-view]").forEach(b=>b.classList.toggle("active",b.dataset.view===view));const target=document.getElementById("main-view"),views={learn:learnView,courses:coursesView,characters:charactersView,leaderboard:leaderboardView,tasks:tasksView,shop:shopView,profile:profilePageView,more:moreView};target.innerHTML=(views[view]||learnView)();if(view==="profile")window.DASLONGOProfile.refreshAvatar()}
    function coursesView(){const enrolled=courseList().filter(item=>state.enrolledCourses.includes(item.id)),catalog=courseList().filter(item=>!state.enrolledCourses.includes(item.id));return `<div class="path-hero"><div><div class="section-kicker">SIZNING SHAXSIY O‘QUV RAFINGIZ</div><h1>Kurslarim</h1><p>Kursni kartochkadan tanlang, istalgan modulga bevosita o‘ting.</p></div><div class="hero-cat">📚</div></div><section class="course-toolbar"><div><div class="section-kicker">O‘RGANAYOTGANLARINGIZ</div><p class="muted text-sm mt-1">${enrolled.length} ta kurs · davom etish yoki boshqa tayyor kursni tanlash mumkin</p></div></section>${enrolled.length?`<div class="course-grid">${enrolled.map(item=>courseCard(item,true)).join("")}</div>`:`<section class="panel p-5"><h2 class="font-black">Hali kurs tanlanmagan</h2><p class="muted">Katalogdan tayyor yo‘nalishni tanlang.</p></section>`}<section class="catalog-header"><div><div class="section-kicker">YO‘NALISHLAR KATALOGI</div><h2 class="font-black text-xl mt-1">Kurs tanlang</h2></div><input id="catalog-search" class="field catalog-search" type="search" placeholder="Kurs qidirish" aria-label="Kurs qidirish"></section><div class="catalog-categories">${["Barchasi","Til","Imtihon","Fan","Sport","Strategiya","Dasturlash","Texnologiya","Ofis"].map(category=>`<button class="simple-tab ${state.catalogCategory===category||(!state.catalogCategory&&category==="Barchasi")?"active":""}" onclick="setCatalogCategory('${category}')">${category}</button>`).join("")}</div><div id="catalog-grid" class="course-grid">${catalog.map(item=>courseCard(item,false)).join("")}</div><section class="plus-insight ${maxHearts()===5?"plus-active":""}"><div class="plus-mark">✦</div><div><div class="section-kicker">DASLONGO PLUS</div><h2>${maxHearts()===5?"Plus o‘quv tahlilingiz":"Ko‘proq imkoniyatlar bilan o‘rganing"}</h2><p>${maxHearts()===5?`${state.enrolledCourses.length} ta kurs tanlangan · ${Object.values(state.completed).reduce((sum,list)=>sum+(list?.length||0),0)} ta modul yakunlangan · ${state.xpEarned} XP ishlangan.`:"Tasdiqlangan Plus hisobida 5 yurak va barcha kurslar bo‘yicha jamlangan o‘quv tahlili mavjud. Obuna xaridi hozircha ulanmagan."}</p></div>${authUser?`<span class="plus-badge">${maxHearts()===5?"PLUS FAOL":"ODDIY HISOB"}</span>`:`<button class="btn3d btn-dark px-4 py-2" onclick="openAccount()">Hisobga kirish</button>`}</section>`}
    function learnerCountLabel(courseId){if(learnerCountsStatus==="loading")return "Hisoblanmoqda…";if(learnerCountsStatus==="unconfigured")return "Hisoblagich sozlanmagan";if(learnerCountsStatus==="error")return "Hisobni yuklab bo‘lmadi";const count=learnerCounts[courseId]||0;return count?`${new Intl.NumberFormat("uz-UZ").format(count)} kishi o‘rganmoqda`:"Hozircha o‘rganuvchi yo‘q"}
    function courseCard(item,isEnrolled){const progress=state.completed[item.id]||[],active=state.course===item.id;return `<article class="catalog-card ${isEnrolled?"catalog-card-enrolled":""} ${active?"catalog-card-active":""}">${isEnrolled?`<span class="catalog-check" aria-label="Kurslaringizda">✓</span><button class="course-remove" onclick="removeCourse('${item.id}')" aria-label="${escapeHtml(item.name)} kursini olib tashlash" title="Kursni olib tashlash">×</button>`:""}<button class="catalog-tile" onclick="${isEnrolled?`selectCourse('${item.id}')`:`enrollCourse('${item.id}')`}" aria-label="${isEnrolled?`${escapeHtml(item.name)} kursini ochish`:`${escapeHtml(item.name)} kursini qo‘shish`}"><span class="catalog-icon">${escapeHtml(item.icon||"📚")}</span><span class="catalog-title">${escapeHtml(item.name)}</span><span class="catalog-learner-count" aria-live="polite">${escapeHtml(learnerCountLabel(item.id))}</span>${isEnrolled&&progress.length?`<span class="catalog-progress">${progress.length}/${item.modules.length} modul</span>`:""}</button></article>`}
    function refreshCourseLearnerCounts(){if(!window.DASLONGOAuth?.isConfigured()){learnerCountsStatus="unconfigured";if(view==="courses")renderView();return}learnerCountsStatus="loading";window.DASLONGOAuth.getCourseLearnerCounts().then(rows=>{learnerCounts=Object.fromEntries((rows||[]).map(row=>[row.course_id,Number(row.learner_count)]));learnerCountsStatus="loaded";if(view==="courses")renderView()}).catch(error=>{console.error("Kurs o‘rganuvchilari sonini yuklab bo‘lmadi:",error);learnerCountsStatus="error";if(view==="courses")renderView()})}
    function syncCourseEnrollment(courseId,removing=false){const update=removing?window.DASLONGOAuth.unenrollFromCourse(courseId):window.DASLONGOAuth.enrollInCourse(courseId);update.then(refreshCourseLearnerCounts).catch(error=>{console.error("Kursga a’zolik serverda yangilanmadi:",error);showToast("Kurs qurilmada yangilandi, lekin umumiy o‘rganuvchilar soni yangilanmadi.")})}
    function syncSavedCourseEnrollments(userId){Promise.allSettled(state.enrolledCourses.map(courseId=>window.DASLONGOAuth.enrollInCourse(courseId))).then(results=>{const failed=results.filter(result=>result.status==="rejected");if(failed.length){console.error(`Saqlangan kurslarni ${userId} hisobiga bog‘lab bo‘lmadi:`,failed.map(result=>result.reason));showToast("Ayrim kurslar hisobingizga sinxronlanmadi. Keyinroq qayta kiring.")}refreshCourseLearnerCounts()})}
    function renderCatalogResults(query=""){const host=document.getElementById("catalog-grid");if(!host)return;const value=query.trim().toLocaleLowerCase("uz"),category=state.catalogCategory||"Barchasi";const results=courseList().filter(item=>!state.enrolledCourses.includes(item.id)&&(!value||`${item.name} ${item.category} ${item.description}`.toLocaleLowerCase("uz").includes(value))&&(category==="Barchasi"||item.category===category));host.innerHTML=results.length?results.map(item=>courseCard(item,false)).join(""):`<div class="panel p-4 muted">Mos tayyor kurs topilmadi.</div>`}
    function learnView(){const c=course(),done=state.completed[c.id]||[],firstIncomplete=c.modules.findIndex((_,index)=>!done.includes(index)),active=firstIncomplete<0?c.modules.length-1:firstIncomplete,progress=Math.round(done.length/c.modules.length*100),finished=done.length===c.modules.length,challengeDone=state.challengeDate===state.dailyDate;return `<div class="path-hero"><div class="hero-copy"><div class="section-kicker">BUGUNGI O‘QUV YO‘LINGIZ</div><h1>${escapeHtml(c.name)}: bilim sari qadam</h1><p>Har kuni ozgina mashq qiling — Momi yo‘lingizni topishda yordam beradi.</p><div class="hero-progress"><div class="hero-progress-track"><span style="width:${progress}%"></span></div><span class="hero-progress-label">${done.length}/${c.modules.length} modul</span></div></div><div class="hero-actions"><div class="hero-cat" aria-label="Momi mushuk">🐈</div><button class="btn3d btn-green hero-start" onclick="startLesson(${active})">${finished?"Takrorlash":done.length?"Davom ettirish":"Darsni boshlash"} <span aria-hidden="true">→</span></button></div></div><section class="daily-challenge"><div class="challenge-copy"><div class="challenge-title">${challengeDone?"✅ Bugungi chaqiriq bajarildi!":"🌟 Momi bilan kunlik chaqiriq"}</div><div class="challenge-description">${challengeDone?"Ertaga yangi savol va yangi imkoniyat!":"Bitta tezkor savolga javob bering, bilimni mustahkamlang."}</div><div class="challenge-reward">${challengeDone?"Mukofot olindi":"Mukofot: +5 XP · kuniga bir marta"}</div></div><button class="btn3d ${challengeDone?"btn-dark":"btn-blue"} px-4 py-2.5" onclick="startDailyChallenge()" ${challengeDone?"disabled":""}>${challengeDone?"Bajarildi":"Boshlash"}</button></section><div class="unit-title"><div><div class="section-kicker">O‘QUV BO‘LIMI · ASOSIY KO‘NIKMALAR</div><h2>${escapeHtml(c.modules[0])}</h2><p>${c.modules.length} modul · keyingisi testdan so‘ng ochiladi</p></div><div class="text-2xl" aria-hidden="true">🧭</div></div><div class="panel map-area"><div class="path-line"></div>${c.modules.map((m,i)=>{const isDone=done.includes(i),isActive=i===active,isLocked=!isDone&&i>active;return `<div class="node-row"><div class="node-wrap ${isActive?"active":""}"><button class="node ${isDone?"done":""} ${isLocked?"locked":""}" ${isLocked?"disabled":""} aria-label="${escapeHtml(m)}${isDone?" — bajarilgan":isActive?" — davom ettirish":" — testdan so‘ng ochiladi"}" onclick="startLesson(${i})">${isDone?"✓":isLocked?"🔒":isActive?"▶":i+1}</button><div class="node-label">${escapeHtml(m)}</div></div></div>`}).join("")}</div><p class="muted text-xs text-center mt-3">Keyingi modulni ochish uchun joriy modul darsini o‘qib, 3 savolli testdan o‘ting.</p>`}
    function tasksView(){const challengeDone=state.challengeDate===state.dailyDate,rows=[["⚡","Bitta modulni yakunlang",Math.min(1,state.dailyModules),1],["✦","Kunlik chaqiriqni bajaring",challengeDone?1:0,1],["📚","10 XP to‘plang",Math.min(10,state.goalXp),10]];return `<div class="path-hero"><div><div class="section-kicker">KUNLIK RITM</div><h1>Vazifalaringiz</h1><p>Kichik maqsadlarni bajaring va odatni mustahkamlang.</p></div><div class="hero-cat">🐈</div></div><section class="daily-challenge"><div class="challenge-copy"><div class="challenge-title">${challengeDone?"✅ Kunlik chaqiriq bajarildi":"🌟 Kunlik bilim chaqirig‘i"}</div><div class="challenge-description">Bir savolga javob bering va qo‘shimcha tajriba oling.</div><div class="challenge-reward">${challengeDone?"Bugun mukofot olindi":"+5 XP · kuniga bir marta"}</div></div><button class="btn3d ${challengeDone?"btn-dark":"btn-blue"} px-4 py-2.5" onclick="startDailyChallenge()" ${challengeDone?"disabled":""}>${challengeDone?"Bajarildi":"Boshlash"}</button></section><section class="panel p-5"><h2 class="font-black text-xl mb-2">Bugungi vazifalar</h2><p class="muted mb-4">Har bir yakunlangan dars sizni maqsadingizga yaqinlashtiradi.</p>${rows.map(([icon,label,value,target])=>`<div class="quest"><div class="quest-icon">${icon}</div><div class="flex-1"><div class="quest-label">${label}</div><div class="quest-progress"><span style="width:${value/target*100}%"></span></div></div><span class="quest-count">${value}/${target}</span></div>`).join("")}</section>`}
    function shopView(){return `<div class="path-hero"><div><div class="section-kicker">XP’NI FOYDALI SARFLANG</div><h1>DASLONGO do‘koni</h1><p>Yuraklarni tiklang yoki o‘rganish seriyangizni asrang.</p></div><div class="hero-cat">🐈</div></div><div class="grid sm:grid-cols-2 gap-4"><article class="course-card"><div class="text-3xl">❤️</div><h2 class="font-black text-lg mt-3">${maxHearts()} ta yurak</h2><p class="muted text-sm min-h-10">Darslarni davom ettirish uchun yuraklaringizni to‘ldiring.</p><div class="flex justify-between items-center mt-4"><span class="font-black">⚡ 50 XP</span><button class="btn3d btn-green px-4 py-2" onclick="buyHearts()">Sotib olish</button></div></article><article class="course-card"><div class="text-3xl">✦</div><h2 class="font-black text-lg mt-3">DASLONGO PLUS</h2><p class="muted text-sm min-h-10">${maxHearts()===5?"Hisobingizda PLUS faol. Siz 5 ta yurakdan foydalanasiz.":"5 ta yurak va boshqa Plus imkoniyatlari. Faollik server tomonidan tasdiqlanadi."}</p><div class="flex justify-between items-center mt-4"><span class="font-black">${maxHearts()===5?"Faol":"Hisob bilan kirish"}</span><button class="btn3d btn-dark px-4 py-2" onclick="openAccount()">${maxHearts()===5?"Profil":"Kirish"}</button></div></article><article class="course-card"><div class="text-3xl">🔥</div><h2 class="font-black text-lg mt-3">Seriya qalqoni</h2><p class="muted text-sm min-h-10">Bir kun o‘qishni unutib qo‘ysangiz, ketma-ketlikni saqlaydi.</p><div class="flex justify-between items-center mt-4"><span class="font-black">⚡ 30 XP · ${state.shields} dona</span><button class="btn3d btn-green px-4 py-2" onclick="buyShield()">Sotib olish</button></div></article></div><div class="panel p-4 mt-4 flex justify-between"><span class="muted">Balansingiz</span><strong>⚡ ${state.xp} XP</strong></div>`}
    function charactersView(){return `<div class="path-hero"><div><div class="section-kicker">SIZNING O‘QUV HAMROHLARINGIZ</div><h1>Qahramonlar</h1><p>O‘zingizga yoqqan hamrohni tanlang. Yangi qahramonlar XP bilan ochiladi.</p></div><div class="hero-cat">${companion().icon}</div></div><div class="panel p-4 mb-4 flex justify-between items-center gap-3"><span class="muted text-sm">Sizning XP balansingiz</span><strong>⚡ ${state.xp} XP</strong></div><div class="character-grid">${CHARACTERS.map(c=>{const unlocked=state.unlockedCharacters.includes(c.id),selected=state.companion===c.id,canUnlock=state.xp>=c.cost;return `<article class="character-card ${selected?"selected":""}"><div class="character-art">${c.icon}</div><h3>${c.name}</h3><div class="section-kicker">${c.title}</div><p class="mt-2">${c.description}</p><button class="btn3d ${selected?"btn-dark":unlocked?"btn-blue":"btn-green"} w-full py-2 mt-4" onclick="unlockOrSelectCharacter('${c.id}')" ${selected?"disabled":!unlocked&&!canUnlock?"disabled":""}>${selected?"Tanlangan":unlocked?"Hamrohni tanlash":`Ochish · ⚡ ${c.cost}`}</button></article>`}).join("")}</div>`}
    function unlockOrSelectCharacter(id){const character=CHARACTERS.find(c=>c.id===id);if(!character){showToast("Qahramon topilmadi.");return}if(!state.unlockedCharacters.includes(id)){if(state.xp<character.cost){showToast(`Bu qahramon uchun ${character.cost} XP kerak.`);return}state.xp-=character.cost;state.unlockedCharacters.push(id)}state.companion=id;save();render();showToast(`${character.name} sizga hamroh bo‘ldi!`)}
    function leaderboardView(){const samples=[{name:"Dilnoza",icon:"🦊",week:80,total:640},{name:"Jasur",icon:"🧑‍💻",week:65,total:520},{name:"Malika",icon:"🧕",week:50,total:410},{name:"Bekzod",icon:"🧑",week:30,total:290},{name:"Aziza",icon:"👩‍🎓",week:15,total:170}];const weekly=state.leagueTab!=="all",rows=[...samples,{name:state.name||"Siz",icon:companion().icon,week:state.goalXp,total:state.xpEarned,me:true}].sort((a,b)=>(weekly?b.week-a.week:b.total-a.total));return `<div class="path-hero"><div><div class="section-kicker">BIRGA O‘RGANISH QIZIQROQ</div><h1>Haftalik liga</h1><p>O‘quv ritmingizni kuzating va o‘z natijangiz bilan faxrlaning.</p></div><div class="hero-cat">🏅</div></div><section class="panel p-5"><div class="section-heading"><div><div class="section-kicker">O‘QUV LIGASI</div><h2>Joriy reyting</h2></div><div class="flex gap-2"><button class="simple-tab ${weekly?"active":""}" onclick="setLeagueTab('week')">Hafta</button><button class="simple-tab ${!weekly?"active":""}" onclick="setLeagueTab('all')">Jami</button></div></div><div class="leader-list">${rows.map((r,i)=>`<article class="leader-row ${r.me?"me":""}"><span class="leader-rank">${["🥇","🥈","🥉"][i]||i+1}</span><div class="flex items-center gap-3"><span class="leader-avatar">${r.icon}</span><div><div class="leader-name">${escapeHtml(r.name)}${r.me?" · siz":""}</div><div class="leader-note">${r.me?"Sizning qurilmangizdagi natija":"Namuna ishtirokchi"}</div></div></div><strong class="text-sm">⚡ ${weekly?r.week:r.total}</strong></article>`).join("")}</div><div class="leader-legend mt-4">ℹ️ Bu namunaviy liga. Hozircha DASLONGO’da hisoblar qurilmangizda saqlanadi — bu ro‘yxat haqiqiy foydalanuvchilar yoki onlayn reyting emas.</div></section>`}
    function setLeagueTab(tab){state.leagueTab=tab;renderView()}
    function moreView(){return `<div class="path-hero"><div><div class="section-kicker">DASLONGO’NI O‘ZINGIZGA MOSLANG</div><h1>Ko‘proq imkoniyatlar</h1><p>Qahramonlar, sozlamalar va o‘rganish ma’lumotlari bir joyda.</p></div><div class="hero-cat">✨</div></div><div class="more-grid"><button class="more-tile" onclick="navigateTo('characters')"><span class="text-2xl">🐾</span><strong>Qahramonlarni tanlash</strong><small>O‘zingizga mos o‘quv hamrohini tanlang.</small></button><button class="more-tile" onclick="navigateTo('leaderboard')"><span class="text-2xl">🏅</span><strong>O‘quv ligasi</strong><small>XP va o‘rganish natijalarini ko‘ring.</small></button><button class="more-tile" onclick="exportProgress()"><span class="text-2xl">📥</span><strong>Ma’lumotni yuklab olish</strong><small>Progress nusxasini JSON faylida saqlang.</small></button><button class="more-tile" onclick="inviteFriends()"><span class="text-2xl">💌</span><strong>Do‘stga ulashish</strong><small>DASLONGO’ni do‘stingizga tavsiya qiling.</small></button><button class="more-tile" onclick="showToast('DASLONGO bir faylli o‘quv loyihasi. Progress shu qurilmada saqlanadi.')"><span class="text-2xl">💡</span><strong>Loyiha haqida</strong><small>O‘rganish yo‘llari va imkoniyatlar haqida.</small></button><button class="more-tile" onclick="resetProgress()"><span class="text-2xl">↺</span><strong>Progressni tozalash</strong><small>Barcha mahalliy natijalarni tasdiq bilan yangilang.</small></button></div><div class="leader-legend mt-4">🔒 Maxfiylik: profil va o‘rganish natijalari shu brauzer qurilmasida saqlanadi. Hisob, sinxronizatsiya va haqiqiy onlayn reyting ulanmagan.</div>`}
    function exportProgress(){try{const blob=new Blob([JSON.stringify({app:"DASLONGO",exportedAt:new Date().toISOString(),progress:state},null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download="daslongo-progress.json";document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);showToast("Progress fayli yuklab olindi.")}catch(error){console.error("Progressni eksport qilib bo‘lmadi:",error);showToast("Progress faylini yaratib bo‘lmadi.")}}
    async function inviteFriends(){const shareData={title:"DASLONGO",text:"DASLONGO’da men bilan texnologiyalarni o‘rganing!",url:location.href};try{if(navigator.share){await navigator.share(shareData);return}if(navigator.clipboard){await navigator.clipboard.writeText(`${shareData.text} ${shareData.url}`);showToast("Taklif matni nusxalandi.");return}showToast("Ulashish uchun brauzer manzil satridagi havolani nusxalang.")}catch(error){if(error.name==="AbortError")return;console.error("Taklifni ulashib bo‘lmadi:",error);showToast("Ulashish amalga oshmadi. Sahifa havolasini nusxalab yuboring.")}}
    function resetProgress(){if(!window.confirm("Barcha DASLONGO progressi va XP’ni shu qurilmadan o‘chirishni xohlaysizmi? Bu amalni qaytarib bo‘lmaydi."))return;try{localStorage.removeItem(KEY);state=loadState();view="learn";render();openOnboarding()}catch(error){console.error("Progressni tozalab bo‘lmadi:",error);showToast("Progressni tozalash amalga oshmadi.")}}
    function profileView(){const totalModules=Object.values(state.completed).reduce((a,x)=>a+x.length,0),badges=[["🌱","Birinchi qadam","Birinchi modulni yakunlang",totalModules>=1],["⚡","XP yig‘uvchi","100 XP to‘plang",state.xpEarned>=100],["🔥","Uch kunlik ritm","3 kun ketma-ket o‘rganing",state.bestStreak>=3],["🏆","Kurs ustasi","Istalgan kursdagi 6 modulni tugating",Object.values(state.completed).some(x=>x.length>=6)]];return `<div class="path-hero"><div><div class="section-kicker">SHAXSIY RIVOJLANISH</div><h1>Salom, ${escapeHtml(state.name)}!</h1><p>Har kuni o‘rganganlaringiz — kelajakdagi imkoniyatlaringiz.</p></div><div class="hero-cat">🐈</div></div><div class="grid sm:grid-cols-2 gap-4"><div class="course-card"><div class="muted text-sm">Jami tajriba</div><div class="text-3xl font-black mt-2">⚡ ${state.xp} XP</div></div><div class="course-card"><div class="muted text-sm">Ketma-ket kunlar</div><div class="text-3xl font-black mt-2">🔥 ${state.streak} kun</div></div><div class="course-card"><div class="muted text-sm">Joriy bosqich</div><div class="text-xl font-black mt-2">${escapeHtml(state.level)}</div></div><div class="course-card"><div class="muted text-sm">Tugallangan modullar</div><div class="text-3xl font-black mt-2">${totalModules}</div></div></div><section class="panel p-5 mt-4"><div class="setting-row"><div><div class="font-black">🎯 Kunlik maqsad</div><div class="muted text-xs mt-1">O‘zingizga mos sur’atni belgilang</div></div><select class="select-course" aria-label="Kunlik maqsadni o‘zgartirish" onchange="setDailyGoal(this.value)"><option value="5" ${state.goal===5?"selected":""}>5 daqiqa</option><option value="10" ${state.goal===10?"selected":""}>10 daqiqa</option><option value="15" ${state.goal===15?"selected":""}>15 daqiqa</option><option value="20" ${state.goal===20?"selected":""}>20 daqiqa</option></select></div></section><section class="panel p-5 mt-4"><div class="flex justify-between items-center gap-3 mb-4"><div><div class="section-kicker">YUTUQLAR</div><h2 class="font-black text-xl mt-1">Sizning nishonlaringiz</h2></div><span class="stat-pill">${badges.filter(x=>x[3]).length}/${badges.length} 🏅</span></div><div class="badge-grid">${badges.map(([icon,name,hint,earned])=>`<article class="badge-card ${earned?"":"locked"}"><div class="badge-icon">${earned?icon:"🔒"}</div><div class="badge-name">${name}</div><div class="badge-hint">${earned?"Ajoyib yutuq!":hint}</div></article>`).join("")}</div></section><div class="panel p-5 mt-4"><div class="section-kicker">KURSLAR</div><p class="muted text-sm">O‘zingizga mos yo‘nalishni tanlang va o‘z sur’atingizda rivojlaning.</p><div class="grid sm:grid-cols-2 gap-3 mt-4">${COURSES.map(c=>`<button class="course-card text-left" onclick="setCourse('${c.id}')"><div class="flex items-center gap-3"><span class="text-2xl">${c.icon}</span><span class="font-black">${c.name}</span></div><div class="muted text-xs mt-2">${(state.completed[c.id]||[]).length}/6 modul</div></button>`).join("")}</div></div>`}
    function profilePageView(){const totalModules=Object.values(state.completed).reduce((sum,items)=>sum+items.length,0),finishedCourses=COURSES.filter(c=>(state.completed[c.id]||[]).length===c.modules.length).length,challengeDone=state.challengeDate===state.dailyDate,achievements=[{icon:"🌱",name:"Birinchi qadam",description:"Birinchi modulni yakunlang",value:Math.min(totalModules,1),target:1},{icon:"⚡",name:"Tajriba to‘plovchi",description:"Jami 100 XP ishlab toping",value:Math.min(state.xpEarned,100),target:100},{icon:"🔥",name:"Olovli odat",description:"3 kun ketma-ket o‘rganing",value:Math.min(state.bestStreak,3),target:3},{icon:"🏆",name:"Kurs ustasi",description:"Bitta kursning barcha modullarini tugating",value:finishedCourses?1:0,target:1},{icon:"🌟",name:"Kunlik chaqiriqlar",description:"5 ta kunlik chaqiriqni bajaring",value:Math.min(state.challengeCount,5),target:5}];return `<section class="social-cover"><div class="profile-avatar">${companion().icon}</div><div class="hero-cat" aria-hidden="true">${companion().icon}</div></section><section class="profile-identity"><div class="flex flex-wrap justify-between items-end gap-3"><div><div class="section-kicker">DASLONGO O‘RGANUVCHISI</div><h1 class="text-2xl font-black mt-1">${escapeHtml(state.name)}</h1><p class="muted text-xs mt-1">Daraja: ${escapeHtml(state.level)} · ${course().name} yo‘nalishi</p></div><button class="btn3d btn-dark px-4 py-2" onclick="navigateTo('more')">⚙️ Sozlamalar</button></div><div class="flex gap-5 mt-4 text-xs"><button class="bg-transparent border-0 text-left text-slate-300" onclick="showToast('Do‘stlar funksiyasi keyingi versiyada ulanadi.')"><strong class="text-white">0</strong> Kuzatayotganlar</button><button class="bg-transparent border-0 text-left text-slate-300" onclick="showToast('Hozircha sizni kuzatayotganlar yo‘q.')"><strong class="text-white">0</strong> Kuzatuvchilar</button><button class="bg-transparent border-0 text-left text-sky-300 font-bold" onclick="inviteFriends()">Do‘stni taklif qilish ↗</button></div></section><div class="profile-stats mt-4"><div class="profile-stat"><strong>🔥 ${state.streak}</strong><span>Joriy seriya · kun</span></div><div class="profile-stat"><strong>⚡ ${state.xpEarned}</strong><span>Jami ishlangan XP</span></div><div class="profile-stat"><strong>📚 ${totalModules}</strong><span>Yakunlangan modullar</span></div><div class="profile-stat"><strong>🏆 ${finishedCourses}/8</strong><span>Tugallangan kurslar</span></div></div><div class="profile-columns"><div class="panel p-4"><div class="section-heading"><div><div class="section-kicker">MAQSADLAR</div><h2>Yutuqlar</h2></div><span class="stat-pill">${achievements.filter(a=>a.value>=a.target).length}/${achievements.length} 🏅</span></div>${achievements.map(a=>`<div class="achievement-row"><div class="achievement-emblem">${a.value>=a.target?a.icon:"🔒"}</div><div><div class="achievement-name">${a.name}</div><div class="achievement-description">${a.description}</div><div class="achievement-progress"><span style="width:${Math.min(100,a.value/a.target*100)}%"></span></div></div><div class="achievement-count">${a.value}/${a.target}</div></div>`).join("")}</div><div class="grid content-start gap-4"><section class="panel p-4"><div class="section-heading"><div><div class="section-kicker">SHAXSIY RIVOJLANISH</div><h2>Kunlik maqsad</h2></div><span>🎯</span></div><label class="muted text-xs" for="profile-goal">Kunlik o‘rganish vaqti</label><select id="profile-goal" class="select-course w-full mt-2" aria-label="Kunlik maqsadni o‘zgartirish" onchange="setDailyGoal(this.value)"><option value="5" ${state.goal===5?"selected":""}>5 daqiqa</option><option value="10" ${state.goal===10?"selected":""}>10 daqiqa</option><option value="15" ${state.goal===15?"selected":""}>15 daqiqa</option><option value="20" ${state.goal===20?"selected":""}>20 daqiqa</option></select><div class="quest-progress mt-3"><span style="width:${Math.min(100,state.goalXp/(state.goal*2)*100)}%"></span></div><div class="muted text-xs mt-2">${state.goalXp}/${state.goal*2} XP bugun</div></section><section class="panel p-4"><div class="section-heading"><div><div class="section-kicker">ALOQADA BO‘LING</div><h2>O‘rganish hamrohlari</h2></div><span>🤝</span></div><p class="muted text-xs leading-5">Do‘stlaringizni taklif qiling, yangi qahramonlarni oching va birga maqsad qo‘ying.</p><div class="profile-links"><button class="profile-link" onclick="navigateTo('characters')"><span>🐾</span> Qahramon tanlash <span class="ml-auto">→</span></button><button class="profile-link" onclick="navigateTo('more')"><span>✨</span> Boshqa imkoniyatlar <span class="ml-auto">→</span></button></div></section></div></div><section class="panel p-4 mt-4"><div class="section-heading"><div><div class="section-kicker">O‘QUV YO‘LLARI</div><h2>Mening kurslarim</h2></div><button class="simple-tab" onclick="navigateTo('learn')">Davom etish →</button></div><div class="grid sm:grid-cols-2 gap-3">${COURSES.map(c=>{const done=(state.completed[c.id]||[]).length,percent=Math.round(done/c.modules.length*100);return `<button class="course-card text-left" onclick="setCourse('${c.id}')"><div class="flex justify-between items-center gap-2"><span class="font-black">${c.icon} ${c.name}</span><span class="muted text-xs">${done}/6</span></div><div class="quest-progress"><span style="width:${percent}%;background:${c.color}"></span></div></button>`}).join("")}</div></section>`}
    function updateAccountUI(){const action=document.getElementById("account-action"),description=document.getElementById("plus-description"),plusAction=document.getElementById("plus-action");if(action)action.textContent=authUser?(authUser.email?.split("@")[0]||"Profil"):"Kirish";if(description)description.textContent=maxHearts()===5?`PLUS faol · 5 yurak · ${state.enrolledCourses.length} ta kurs va ${Object.values(state.completed).reduce((sum,list)=>sum+(list?.length||0),0)} ta tugallangan modul bo‘yicha tahlil.`:"Tasdiqlangan Plus hisobida 5 yurak, tanlangan kurslar va bajarilgan modullar bo‘yicha jamlangan ko‘rsatkichlar mavjud.";if(plusAction)plusAction.textContent=authUser?"Profilni ochish":"Hisobga kirish"}
    function handleAuthSession(user,isReady=true){if(!isReady)return;const previousLimit=maxHearts();authUser=user;authReady=true;const limit=maxHearts();if(limit>previousLimit)state.hearts=limit;else if(limit<previousLimit){state.hearts=Math.min(state.hearts,limit);state.lastHeartAt=Date.now()}const name=user?.user_metadata?.full_name;if(name&&(!state.onboarded||state.name==="O‘rganuvchi"))state.name=name;if(user?.id&&lastEnrollmentSyncUserId!==user.id){lastEnrollmentSyncUserId=user.id;syncSavedCourseEnrollments(user.id)}else if(!user){lastEnrollmentSyncUserId="";onboardingUserId=""}save();render();if(user&&!state.onboarded&&onboardingUserId!==user.id){onboardingUserId=user.id;openOnboarding()}}
    function openAccount(mode="login"){if(authUser){navigateTo("profile");return}window.DASLONGOAuth.open(mode)}
    const originalProfilePageView=profilePageView;
    profilePageView=function(){let markup=originalProfilePageView();markup=markup.replace(`<div class="profile-avatar">${companion().icon}</div>`,`<div class="profile-avatar"><span id="profile-avatar-fallback">${companion().icon}</span><img id="profile-avatar-image" class="hidden" alt="Profil rasmi"><label class="avatar-upload-btn" for="avatar-upload" title="Profil rasmini yuklash">＋</label><input id="avatar-upload" class="hidden" type="file" accept="image/*"><button class="avatar-remove-btn" type="button" data-remove-avatar aria-label="Profil rasmini olib tashlash" title="Rasmni olib tashlash">×</button></div>`);const accountCard=authUser?`<section class="account-card"><div><div class="section-kicker">DASLONGO HISOBI</div><strong>${escapeHtml(authUser.email||"Tizimga kirilgan")}</strong><p>${maxHearts()===5?"✦ PLUS faol · 5 ta yurak":"Bepul hisob · 3 ta yurak"}</p></div><button class="btn3d btn-dark px-4 py-2" onclick="window.DASLONGOAuth.signOut()">Hisobdan chiqish</button></section>`:`<section class="account-card"><div><div class="section-kicker">HISOBNI SINXRONLASH</div><strong>Progressingizni hisob bilan saqlang</strong><p>Email, Google, Apple yoki GitHub orqali kiring.</p></div><button class="btn3d btn-green px-4 py-2" onclick="window.DASLONGOAuth.open('signup')">Hisob yaratish</button></section>`;return markup.replace('<section class="profile-identity">',`${accountCard}<section class="profile-identity">`)}
    function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
    function setCourse(id){if(!courseList().some(item=>item.id===id)){showToast("Kurs topilmadi.");return}if(!state.enrolledCourses.includes(id)){state.enrolledCourses.push(id);if(authUser)syncCourseEnrollment(id)}state.course=id;save();view="learn";render()}
    function selectCourse(id){setCourse(id);navigateTo("learn")}
    function enrollCourse(id){const item=courseList().find(courseItem=>courseItem.id===id);if(!item){showToast("Kurs topilmadi.");return}const isNew=!state.enrolledCourses.includes(id);if(isNew)state.enrolledCourses.push(id);state.course=id;save();view="courses";render();if(isNew&&authUser)syncCourseEnrollment(id);showToast(`“${item.name}” kursi kurslaringizga qo‘shildi.`)}
    function removeCourse(id){if(state.enrolledCourses.length<=1){showToast("Kamida bitta kurs kurslaringizda qolishi kerak.");return}const name=courseList().find(item=>item.id===id)?.name;if(!name)return;if(!window.confirm(`“${name}” kursini ro‘yxatingizdan olib tashlaysizmi? Tugallangan progress saqlanadi.`))return;state.enrolledCourses=state.enrolledCourses.filter(courseId=>courseId!==id);if(state.course===id){state.course=state.enrolledCourses[0]}save();render();if(authUser)syncCourseEnrollment(id,true)}
    function setCatalogCategory(category){state.catalogCategory=category;document.querySelectorAll(".catalog-categories .simple-tab").forEach(button=>button.classList.toggle("active",button.textContent===category));renderCatalogResults(document.getElementById("catalog-search")?.value||"")}
    function setDailyGoal(value){const goal=Number(value);if(![5,10,15,20].includes(goal)){showToast("Kunlik maqsad qiymati noto‘g‘ri.");return}state.goal=goal;save();render();showToast(`Kunlik maqsad ${goal} daqiqaga o‘zgartirildi.`)}
    document.addEventListener("input",event=>{if(event.target.id==="catalog-search")renderCatalogResults(event.target.value)});
    document.addEventListener("click",event=>{const button=event.target.closest("[data-view]");if(button)navigateTo(button.dataset.view)});
    let toastTimer;function showToast(msg){const t=document.getElementById("toast");t.textContent=msg;t.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove("show"),2500)}window.showToast=showToast;
    function buyHearts(){const limit=maxHearts();if(state.hearts>=limit){showToast("Yuraklaringiz hozir to‘liq!");return}if(state.xp<50){showToast("Yuraklar uchun 50 XP kerak.");return}state.xp-=50;state.hearts=limit;state.lastHeartAt=Date.now();save();render();showToast(`${limit} ta yurak balansingizga qo‘shildi!`)}
    function buyShield(){if(state.xp<30){showToast("Qalqon uchun 30 XP kerak.");return}state.xp-=30;state.shields+=1;save();render();showToast("Seriya qalqoni xarid qilindi. Bir kunlik tanaffusni yopadi.")}
    function moduleQuestions(selectedCourse,moduleIndex){const lessons=selectedCourse.modules.map((_,index)=>courseLesson(selectedCourse,index));if(!lessons[moduleIndex]||!Array.isArray(lessons[moduleIndex].takeaways)||lessons[moduleIndex].takeaways.length<3)throw new Error(`Modul uchun kamida 3 ta test javobi kerak: ${selectedCourse.id}/${moduleIndex}`);const distractors=lessons.flatMap((item,index)=>item?.takeaways?.map(text=>({text,index}))||[]).filter(item=>item.index!==moduleIndex);return lessons[moduleIndex].takeaways.slice(0,3).map((fact,questionIndex)=>{const pool=[...new Set(distractors.map(item=>item.text).filter(text=>text!==fact))];if(pool.length<3)throw new Error(`Test uchun chalg‘ituvchi javoblar yetarli emas: ${selectedCourse.id}/${moduleIndex}`);const first=(moduleIndex*3+questionIndex*3)%pool.length,wrong=[0,1,2].map(offset=>pool[(first+offset)%pool.length]),correctIndex=(moduleIndex+questionIndex)%4,answers=wrong.slice();answers.splice(correctIndex,0,fact);return {q:`“${selectedCourse.modules[moduleIndex]}” mavzusiga mos fikrni tanlang.`,a:answers,ok:correctIndex,tip:fact}})}
    function canOpenModule(index,selectedCourse=course()){if(!Number.isInteger(index)||index<0||index>=selectedCourse.modules.length)return false;const done=state.completed[selectedCourse.id]||[];if(done.includes(index))return true;const next=selectedCourse.modules.findIndex((_,moduleIndex)=>!done.includes(moduleIndex));return next===-1||index===next}
    function startLesson(index){heartRefresh();if(!Number.isInteger(index)||index<0||index>=course().modules.length)return;if(!canOpenModule(index)){showToast("Keyingi modulni ochish uchun joriy modul testidan o‘ting.");return}if(state.hearts<=0){showToast("Yuraklaringiz tugadi. Do‘kondan oling yoki tiklanishini kuting.");return}const c=course();try{lesson={index,questions:moduleQuestions(c,index),questionIndex:0,answered:false,challenge:false,stage:"study"}}catch(error){console.error("Modulni ochib bo‘lmadi:",error);showToast("Bu modul darsini hozir ochib bo‘lmadi.");return}document.getElementById("lesson-modal").classList.remove("hidden");renderLesson()}
    function jumpLesson(index){if(!lesson||lesson.challenge||!Number.isInteger(index)||index<0||index>=course().modules.length)return;if(!canOpenModule(index)){showToast("Boshqa modulga o‘tishdan oldin testni yakunlang.");return}if(state.hearts<=0){showToast("Yuraklaringiz tugadi. Do‘kondan oling yoki tiklanishini kuting.");return}try{lesson={index,questions:moduleQuestions(course(),index),questionIndex:0,answered:false,selected:null,challenge:false,stage:"study"};renderLesson()}catch(error){console.error("Modulga o‘tib bo‘lmadi:",error);showToast("Modulni ochib bo‘lmadi.")}}
    function lessonNavigator(index){if(lesson?.challenge)return "";const modules=course().modules,canPrevious=canOpenModule(index-1),canNext=canOpenModule(index+1);return `<nav class="lesson-module-nav" aria-label="Modullar orasida o‘tish"><button class="btn3d btn-dark px-3 py-2" onclick="jumpLesson(${index-1})" ${!canPrevious?"disabled":""}>← Avvalgi modul</button><span>${index+1} / ${modules.length}</span><button class="btn3d btn-dark px-3 py-2" onclick="jumpLesson(${index+1})" ${!canNext?"disabled":""}>Keyingi modul →</button></nav>${!canNext&&index<modules.length-1?`<p class="module-gate-note">Keyingi modul testni muvaffaqiyatli tugatgach ochiladi.</p>`:""}`}
    function startDailyChallenge(){refreshDailyState();if(state.challengeDate===state.dailyDate){showToast("Bugungi chaqiriqni allaqachon bajardingiz!");return}if(state.hearts<=0){showToast("Chaqiriq uchun kamida bitta yurak kerak.");return}const questions=moduleQuestions(course(),0),index=Math.floor(new Date(`${state.dailyDate}T00:00:00`).getTime()/86400000)%questions.length;lesson={index:0,questions:[questions[index]],questionIndex:0,answered:false,challenge:true,stage:"quiz"};document.getElementById("lesson-modal").classList.remove("hidden");renderLesson()}
    function beginLessonTest(){if(!lesson||lesson.challenge||lesson.stage!=="study")return;lesson.stage="quiz";lesson.questionIndex=0;lesson.selected=null;lesson.answered=false;renderLesson()}
    function renderLessonStudy(){const item=courseLesson(course(),lesson.index);if(!item){console.error("Dars matni topilmadi:",course().id,lesson.index);showToast("Dars matni yuklanmadi. Keyinroq qayta urinib ko‘ring.");return}document.getElementById("lesson-hearts").textContent=state.hearts;document.getElementById("lesson-progress").style.width="0%";document.getElementById("lesson-content").innerHTML=`<div class="section-kicker">MODUL ${lesson.index+1} / ${course().modules.length} · O‘RGANISH</div><h2 id="lesson-title">${escapeHtml(course().modules[lesson.index])}</h2>${lessonNavigator(lesson.index)}<div class="lesson-reading">${item.paragraphs.map(paragraph=>`<p>${escapeHtml(paragraph)}</p>`).join("")}<pre class="lesson-example"><code>${escapeHtml(item.example)}</code></pre><section class="lesson-takeaways"><h3>Esda tuting</h3><ul>${item.takeaways.map(point=>`<li>${escapeHtml(point)}</li>`).join("")}</ul></section></div><div class="modal-footer lesson-footer"><span class="muted text-xs">Avval o‘qing, so‘ng bilimni testda tekshiring.</span><button class="btn3d btn-green px-5 py-3" onclick="beginLessonTest()">O‘rgandim — testni boshlash</button></div>`}
    function renderLesson(feedback=""){const l=lesson;if(!l)return;if(l.stage==="study"){renderLessonStudy();return}const q=l.questions[l.questionIndex],lastQuestion=l.questionIndex===l.questions.length-1;document.getElementById("lesson-hearts").textContent=state.hearts;document.getElementById("lesson-progress").style.width=`${((l.questionIndex+(feedback==="success"?1:0))/l.questions.length)*100}%`;document.getElementById("lesson-content").innerHTML=`<div class="section-kicker">${l.challenge?"KUNLIK CHAQIRIQ":"MODUL "+(l.index+1)+" / 6"} · SAVOL ${l.questionIndex+1} / ${l.questions.length}</div><h2 id="lesson-title">${l.challenge?"Momi bilan bilim sinovi":escapeHtml(course().modules[l.index])}</h2>${lessonNavigator(l.index)}<p class="lead">${l.challenge?"Bitta savol — bitta yangi bilim. To‘g‘ri javob uchun +5 XP!":"Momi savol berdi — eng to‘g‘ri javobni tanlang."}</p><div class="panel p-4 my-5"><div class="text-sm font-bold">${escapeHtml(q.q)}</div></div><div class="grid gap-2">${q.a.map((a,i)=>`<button class="lesson-option ${l.selected===i?(i===q.ok?"correct":"wrong"):""}" ${l.answered?"disabled":""} onclick="answerLesson(${i})">${String.fromCharCode(65+i)}. ${escapeHtml(a)}</button>`).join("")}</div>${feedback?`<div class="mt-4 p-4 rounded-xl ${feedback==="success"?"bg-green-950/60":"bg-red-950/50"}"><div class="font-black">${feedback==="success"?"Ajoyib! To‘g‘ri javob!":"Yana bir bor urinib ko‘ring."}</div><div class="text-sm muted mt-1">${feedback==="success"?escapeHtml(q.tip):"Javobni qayta tanlashingiz mumkin. Yuraklar tugasa, dars to‘xtaydi."}</div></div>`:""}<div class="modal-footer">${feedback==="success"?`<span class="text-sm font-black text-lime-400">${lastQuestion?(l.challenge?"+5 XP":"+10 XP"):"Savol bajarildi"}</span><button class="btn3d btn-green px-6 py-3" onclick="nextLessonQuestion()">${lastQuestion?(l.challenge?"Mukofotni olish":"Modulni yakunlash"):"Davom etish"}</button>`:feedback==="failed"?`<span class="text-sm text-red-300">Dars to‘xtatildi</span><button class="btn3d btn-dark px-6 py-3" onclick="closeLesson()">Yopish</button>`:`<span class="muted text-xs">Har bir xatoda bitta yurak kamayadi.</span><button class="btn3d btn-blue px-6 py-3" onclick="submitLesson()" ${l.selected==null?"disabled":""}>Tekshirish</button>`}</div>`}
    function answerLesson(i){if(lesson.answered)return;lesson.selected=i;renderLesson()}
    function submitLesson(){if(!lesson||lesson.selected==null)return;lesson.answered=true;if(lesson.selected===lesson.questions[lesson.questionIndex].ok){renderLesson("success");return}state.hearts=Math.max(0,state.hearts-1);if(state.hearts===maxHearts()-1)state.lastHeartAt=Date.now();save();render();if(state.hearts===0){lesson.answered=false;renderLesson("failed")}else{lesson.answered=false;lesson.selected=null;renderLesson("wrong")}}
    function nextLessonQuestion(){if(!lesson)return;if(lesson.questionIndex===lesson.questions.length-1){if(lesson.challenge)finishDailyChallenge();else finishLesson();return}lesson.questionIndex++;lesson.answered=false;lesson.selected=null;renderLesson()}
    function updateStreak(){const today=localDateKey();if(state.lastVisit!==today){const last=state.lastVisit?new Date(`${state.lastVisit}T12:00:00`):null,current=new Date(`${today}T12:00:00`),gap=last?Math.round((current-last)/86400000):Infinity;if(gap===1)state.streak+=1;else if(gap===2&&state.shields>0){state.shields-=1;state.streak+=2;showToast("Seriya qalqoni ishladi — ketma-ketlik saqlandi!")}else state.streak=1;state.lastVisit=today;state.bestStreak=Math.max(state.bestStreak,state.streak)}}
    function finishDailyChallenge(){if(!lesson||!lesson.challenge)return;state.challengeDate=state.dailyDate;state.challengeCount+=1;state.xp+=5;state.xpEarned+=5;state.goalXp+=5;updateStreak();save();closeLesson();render();showToast("Kunlik chaqiriq bajarildi — +5 XP!")}
    function finishLesson(){if(!lesson)return;const done=state.completed[state.course]||(state.completed[state.course]=[]),isNew=!done.includes(lesson.index);if(isNew)done.push(lesson.index);const reward=isNew?10:0;if(isNew){state.xp+=reward;state.xpEarned+=reward;state.goalXp+=reward;state.dailyModules+=1}updateStreak();save();closeLesson();render();showToast(isNew?"Modul yakunlandi — +10 XP!":"Takrorlash tugadi — yangi modulni davom ettiring.")}
    function closeLesson(){lesson=null;document.getElementById("lesson-modal").classList.add("hidden")}
    document.getElementById("lesson-close").addEventListener("click",closeLesson);
    document.getElementById("lesson-modal").addEventListener("click",e=>{if(e.target.id==="lesson-modal")closeLesson()});
    const onboardSteps=[
      {title:"Salom, kelajak bilimdoni!",lead:"Momi mushuk bilan tanishing — u sizga til, fan, dasturlash va boshqa yo‘nalishlarni o‘rganishda hamroh bo‘ladi. Ismingiz nima?",type:"name",options:[]},
      {title:"Bizni qayerdan topdingiz?",lead:"DASLONGO haqida qayerdan eshitdingiz?",type:"choice",options:["Do‘stim yoki hamkasbimdan","Ijtimoiy tarmoqlardan","Qidiruv tizimidan","Boshqa joydan"]},
      {title:"Kuniga qancha vaqt ajratasiz?",lead:"O‘zingizga mos maqsadni tanlang. Uni keyinchalik o‘zgartirish mumkin.",type:"choice",options:["5 daqiqa — yengil boshlanish","10 daqiqa — muntazam qadam","15 daqiqa — faol mashg‘ulot","20 daqiqa — jiddiy maqsad"]},
      {title:"Hozirgi darajangiz qanday?",lead:"Sizga mos boshlang‘ich nuqtani topish uchun bir savol. Istalgan vaqtda yo‘nalishni o‘zgartira olasiz.",type:"level",options:["Yangi boshlovchiman","Asoslarni bilaman","Amaliy tajribam bor"]},
      {title:"Tayyor bo‘lsangiz, boshlaymiz!",lead:"Sizga mos o‘quv yo‘li tuzildi. Birinchi yo‘nalishni tanlab, ilk mashqni bajaring.",type:"done",options:[]}
    ];
    function openOnboarding(){onboardStep=0;onboardData={referral:"",goal:10,level:"Boshlovchi",name:""};renderOnboarding();document.getElementById("onboarding").classList.remove("hidden")}
    function renderOnboarding(){const step=onboardSteps[onboardStep],host=document.getElementById("onboard-content");document.getElementById("step-dots").innerHTML=onboardSteps.map((_,i)=>`<span class="${i<=onboardStep?"on":""}"></span>`).join("");document.getElementById("onboard-back").style.visibility=onboardStep===0?"hidden":"visible";document.getElementById("onboard-next").textContent=onboardStep===4?"O‘rganishni boshlash":"Davom etish";let body="";
      if(step.type==="name")body=`<div class="text-5xl my-4">🐈</div><input id="onboard-name" class="field" placeholder="Ismingiz" maxlength="24" value="${escapeHtml(onboardData.name)}" aria-label="Ismingiz">`;
      if(step.type==="choice")body=`<div class="grid gap-2 mt-5">${step.options.map((o,i)=>{let selected=onboardStep===1?onboardData.referral===o:onboardData.goal===(i===0?5:i===1?10:i===2?15:20);return `<button class="choice ${selected?"selected":""}" onclick="chooseOnboard(${i})">${o}</button>`}).join("")}</div>`;
      if(step.type==="level")body=`<div class="grid gap-2 mt-5">${step.options.map((o,i)=>`<button class="choice ${onboardData.level===["Boshlovchi","Asosiy","Tajribali"][i]?"selected":""}" onclick="chooseOnboard(${i})">${o}</button>`).join("")}<div class="panel p-4 mt-3"><div class="font-black">Mini daraja savoli</div><p class="muted text-sm mb-0">Python’da ro‘yxatning birinchi elementi odatda qaysi indeksda turadi?</p><div class="flex gap-2 mt-3"><button class="btn3d btn-dark px-4 py-2" onclick="onboardData.level='Boshlovchi';renderOnboarding()">0</button><button class="btn3d btn-dark px-4 py-2" onclick="onboardData.level='Asosiy';renderOnboarding()">1</button></div></div>`;
      if(step.type==="done")body=`<div class="text-5xl my-4">🎉</div><div class="panel p-4 mt-5 flex items-center gap-3"><span class="text-3xl">🐈</span><div><div class="font-black">Ajoyib, ${escapeHtml(onboardData.name||"do‘stim")}!</div><div class="muted text-sm">Kunlik maqsadingiz: ${onboardData.goal} daqiqa · Daraja: ${onboardData.level}</div></div></div><div class="grid grid-cols-2 gap-3 mt-4">${courseList().filter(c=>!c.custom).map(c=>`<button class="choice !m-0 !p-3 text-center ${state.course===c.id?"selected":""}" onclick="chooseCourseOnboarding('${c.id}',this)"><span class="text-xl">${c.icon}</span><br><span class="text-xs">${escapeHtml(c.name)}</span></button>`).join("")}</div>`;
      host.innerHTML=`<div class="section-kicker">BOSHLANG‘ICH SOZLASH · ${onboardStep+1}/5</div><h2 id="onboard-title">${step.title}</h2><p class="lead">${step.lead}</p>${body}`;
      document.getElementById("onboard-next").disabled=(step.type==="choice"&&onboardStep===1&&!onboardData.referral)||(step.type==="name"&&!onboardData.name.trim());document.getElementById("onboard-next").style.opacity=document.getElementById("onboard-next").disabled?".5":"1";
      const input=document.getElementById("onboard-name");if(input)input.addEventListener("input",()=>{onboardData.name=input.value;document.getElementById("onboard-next").disabled=!input.value.trim();document.getElementById("onboard-next").style.opacity=input.value.trim()?"1":".5"})}
    function chooseOnboard(i){if(onboardStep===1)onboardData.referral=onboardSteps[1].options[i];if(onboardStep===2)onboardData.goal=[5,10,15,20][i];if(onboardStep===3)onboardData.level=["Boshlovchi","Asosiy","Tajribali"][i];renderOnboarding()}
    function chooseCourseOnboarding(id,button){state.course=id;if(!state.enrolledCourses.includes(id)){state.enrolledCourses.push(id);if(authUser)syncCourseEnrollment(id)}document.querySelectorAll("#onboard-content .choice").forEach(x=>x.classList.remove("selected"));button.classList.add("selected")}
    document.getElementById("onboard-back").addEventListener("click",()=>{if(onboardStep>0){onboardStep--;renderOnboarding()}});
    document.getElementById("onboard-next").addEventListener("click",()=>{const current=onboardSteps[onboardStep];if(current.type==="name"){onboardData.name=(document.getElementById("onboard-name")?.value||"").trim();if(!onboardData.name)return}if(onboardStep<onboardSteps.length-1){onboardStep++;renderOnboarding();return}state.name=onboardData.name||"O‘rganuvchi";state.goal=onboardData.goal;state.level=onboardData.level;state.referral=onboardData.referral;state.onboarded=true;save();document.getElementById("onboarding").classList.add("hidden");render()});
    window.DASLONGOAuth.init(handleAuthSession);render();setInterval(()=>{if(!authUser)return;const previousHearts=state.hearts,previousDate=state.dailyDate;refreshDailyState();heartRefresh();if(previousHearts!==state.hearts||previousDate!==state.dailyDate)render()},60_000);
